const floorBoxes=[...document.querySelectorAll('[data-level]')];
const levels={3:-2.87,0:0,1:3.58,2:6.95,4:8.5};
function isExploring(){return ui.mode.value!=='all'||+ui.explode.value>0||floorBoxes.some(b=>!b.checked);}
function visible(o){
 if(!isStateActive(o))return false;
 if(fixtureIndexSet.has(facadeSourceIndex(o))&&lightingMode!=='night')return false;
 if(parcelScope==='parcel'&&exteriorIndexSet.has(facadeSourceIndex(o)))return false;
 if(facadeState[facadeFor(o)]===false||!variantVisible(o))return false;
 if(!ui.furn.checked&&furnishings(o))return false;
 const mode=ui.mode.value;
 if(o.level===5)return ui.context.checked;
 if(!floorBoxes.find(b=>+b.dataset.level===o.level)?.checked)return false;
 if(mode==='stairs')return /escalera|barandilla|descansillo/.test(o.name);
 if(mode==='roof'&&o.level!==4)return false;
 if(!['all','roof'].includes(mode)&&o.level!==+mode)return false;
 return true;
}
function offset(o){const ex=+ui.explode.value;return o.level===4?ex*3:o.level===5?0:o.level===3?-ex:ex*o.level;}
function frame(){const m=ui.mode.value;target=m==='stairs'?(state==='actual'?[4.4,4.9,3.2]:[4.2,-.2,3.8]):[0,0,m==='all'?4:levels[m==='roof'?4:+m]+1.2];distance=m==='stairs'?(state==='actual'?22:16):m==='all'?37+(+ui.explode.value)*2:29;}
function update(){const titles={all:'Todas las plantas',stairs:state==='actual'?'Escalera actual':'Escalera reformada',roof:'Cubierta',0:'Planta baja',1:'Planta primera',2:'Planta segunda',3:'Semisótano'};
 ui.explode.disabled=false;
 document.getElementById('orbitMode').setAttribute('aria-pressed',String(!walkUI.active&&navigationMode==='orbit'));document.getElementById('panMode').setAttribute('aria-pressed',String(!walkUI.active&&navigationMode==='pan'));
 document.getElementById('status').textContent=walkUI.active?'Recorrido interior · Altura de cámara ajustable':'Marketing · '+(state==='actual'?'Actual':'Reformada')+' · '+titles[ui.mode.value];
 document.getElementById('separation').textContent=+ui.explode.value?(+ui.explode.value).toFixed(1)+' m adicionales entre plantas':'Sin separación';
 document.getElementById('detail').textContent=walkUI.active?'Altura de cámara ajustable · Movimiento sobre suelos y escaleras · Esc para salir':interiorStart?'Vista interior · Pulsa Recorrer para caminar':'Arrastra para explorar · Rueda para acercar';draw();}
