    let pos=interiorStart?this.world.spawn(interiorStart.pos.slice(0,2),interiorStart.pos[2]):null;for(const p of (pos?[]:starts[level])){pos=this.world.spawn(p,levels[level]);if(pos)break;}
    if(!pos)throw Error('No se encontró un punto de entrada libre en esta planta. Prueba otra vista interior.');
    this.saved={yaw,pitch,distance,target:target.slice(),orthographic,mode:ui.mode.value,explode:ui.explode.value,checks:floorBoxes.map(b=>b.checked),furn:ui.furn.checked,context:ui.context.checked};
    this.walker=new Walker(this.world,pos);if(interiorStart){this.walker.angle=interiorStart.angle;this.walker.pitch=0;}this.active=true;document.getElementById('doorReticle').hidden=false;this.keys.clear();
    orthographic=false;
    document.getElementById('walkExit').hidden=false;document.getElementById('walkOverlay').hidden=false;
    button.setAttribute('aria-pressed','true');
    msg.textContent='WASD o flechas: caminar. Arrastra para mirar. Acércate y usa E o clic sobre una hoja para abrirla o cerrarla. Esc: salir.';
