document.getElementById('walkStart').onclick=()=>walkUI.start();
document.getElementById('walkExit').onclick=()=>walkUI.exit();
document.getElementById('walkOverlayExit').onclick=()=>walkUI.exit();
const walkKeys=new Set(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight']);
document.addEventListener('keydown',e=>{
 if(!walkUI.active||/^(INPUT|SELECT|TEXTAREA)$/.test(e.target?.tagName)||e.target?.isContentEditable)return;
 if(e.code==='Escape'){e.preventDefault();walkUI.exit();return;}
 if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;
 if(e.code==='KeyE'){e.preventDefault();if(!e.repeat)walkUI.interact();return;}
 if(walkKeys.has(e.code)){e.preventDefault();walkUI.keys.add(e.code);}
});
document.addEventListener('keyup',e=>{if(walkKeys.has(e.code)){if(walkUI.active)e.preventDefault();walkUI.keys.delete(e.code);}});
window.addEventListener('blur',()=>{walkUI.keys.clear();walkUI.drag=null;});
document.addEventListener('visibilitychange',()=>{if(document.hidden)walkUI.keys.clear();});
function variantVisible(){return true;}
for(const side of ['N','S','E','O'])document.getElementById('facade'+side).onchange=e=>{facadeState[side]=e.target.checked;draw();};
document.getElementById('restoreFacades').onclick=()=>{for(const s of ['N','S','E','O']){facadeState[s]=true;document.getElementById('facade'+s).checked=true;}draw();};
function popover(button,panel){const b=document.getElementById(button),p=document.getElementById(panel);b.onclick=()=>{p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden));};}
popover('separateToggle','separatePanel');popover('helpToggle','helpPanel');
document.getElementById('separateClose').onclick=()=>{ui.explode.value='0';document.getElementById('separatePanel').hidden=true;document.getElementById('separateToggle').setAttribute('aria-expanded','false');update();};
document.getElementById('panelToggle').onclick=()=>{const p=document.getElementById('controls'),open=p.getAttribute('data-closed')!=='false';p.setAttribute('data-closed',String(!open));document.getElementById('panelToggle').setAttribute('aria-expanded',String(open));};
document.getElementById('fullscreen').onclick=async()=>{try{if(document.fullscreenElement||document.webkitFullscreenElement){await (document.exitFullscreen?.()||document.webkitExitFullscreen?.());}else{const el=document.documentElement;if(el.requestFullscreen)await el.requestFullscreen();else if(el.webkitRequestFullscreen)el.webkitRequestFullscreen();else document.getElementById('walkMessage').textContent='Pantalla completa no disponible en este navegador.';}}catch(e){document.getElementById('walkMessage').textContent='No se pudo activar la pantalla completa.';}};
function fullscreenState(){const full=!!(document.fullscreenElement||document.webkitFullscreenElement);document.getElementById('fullscreen').setAttribute('aria-label',full?'Salir de pantalla completa':'Pantalla completa');draw();}
